# DK RBB.  Rødekro - Bredebro
#
let rb = path("d3.dk.rbb");

with detail = 4, railway = :first :pax :removed {
    # point.dk.Rødekro  dk.FPB

    with link = "line.dk.RBB" {
        track(:ror,
                rb[:rod.yb - 0.1dl, :rod.yb] << 0.5mo
            ..  rb[:rod.xb + 1mo, :rod.xb + 1.1mo]
        );
        track(rb[:rod.xb + 1mo, :nho - 0.49sw]);
    }

    with link = "point.dk.Nørre-Hostrup", railway = :station {
        track(rb[:nho - 0.5sw, :nho + 0.5sw]);
        marker(:left :de.hst :casing, rb[:nho] << 0.5mt);
        station(:right, rb[:nho] << 0.5mt << 1sh + (2dt, 1.8dt),
            "Nørre Hostrup", "RBB: 4,9"
        );
    }

    with link = "line.dk.RBB" {
        track(rb[:nho + 0.49sw, :hel - 0.49sw]);
    }

    with link = "point.dk.Hellevad", railway = :station {
        track(rb[:hel - 0.5sw, :hel + 0.5sw]);
        marker(:left :de.bf, rb[:hel] << 0.5mt);
        station(:bottom, rb[:hel] << 0.5mt << 1sh << 0.8dt,
            "Hellevad", "RBB: 9,2"
        );
    }

    with link = "line.dk.RBB" {
        track(rb[:hel + 0.49sw, :hel.yv]);
        track(rb[:hel.yv, :hem - 0.49sw]);
        track(:station, rb[:hem - 0.5sw, :hem + 0.5sw]);
        track(rb[:hem + 0.49sw, :kla - 0.49sw]);
        track(:station, rb[:kla - 0.5sw, :kla + 0.5sw]);
        track(rb[:kla + 0.49sw, :klo - 0.49sw]);
    }

    with link = "point.dk.Klovtoft", railway = :station {
        track(rb[:klo - 0.5sw, :klo + 0.5sw]);
        marker(:right :de.hst, rb[:klo] >> 0.5mt);
        station(:top, rb[:klo] >> 0.5mt >> 1sh + (-1.5dt, -1.2dt),
            "Klovtoft", "RBB: 12,1"
        );
    }

    with link = "line.dk.RBB" {
        track(rb[:klo + 0.49sw, :siv - 0.49sw]);
        track(:station, rb[:siv - 0.5sw, :siv + 0.5sw]);
        track(rb[:siv + 0.49sw, :bea - 0.49sw]);
        track(:station, rb[:bea - 0.49sw, :bea + 0.49sw]);
        track(rb[:bea + 0.49sw, :bed - 0.49sw]);
    }

    with link = "point.dk.Bedsted-Løgum", railway = :station {
        track(rb[:bed - 0.5sw, :bed + 0.5sw]);
        marker(:right :de.bf :casing, rb[:bed] >> 0.5mt);
        station(:top:left_align, rb[:bed] >> 0.5mt >> 1sh + (-3dt, -0.8dt),
            "Bedsted Løgum", " RBB: 16,7"
        );
    }

    with link = "line.dk.RBB" {
        track(rb[:bed + 0.49sw, :bed + 1.01km]);
        line_label(:left:n, rb[:bed + 1km] << 0.5mt, (0.4dt, 0dt), "RBB");
        track(rb[:bed + 0.99km, :sgr.xo + 0.1dl]);
        track(:ror, rb[:sgr.xo, :sgr.xv]);
        track(rb[:sgr.xv - 0.1dl, :als - 0.89km]);
        line_label(:right:se, rb[:als - 0.9km] >> 0.5mt, "RBB");
        track(rb[:als - 0.91km, :als - 0.49sw]);
    }

    with link = "point.dk.Alslev-Kro", railway = :station {
        track(rb[:als - 0.5sw, :als + 0.5sw]);
        marker(:left :de.hst, rb[:als] << 0.5mt);
        station(:top, rb[:als] >> 0.5mt >> 1.3dt,
            "Alslev Kro", "RBB: 22,4"
        );
    }

    with link = "line.dk.RBB" {
        track(rb[:als + 0.49sw, :ass.yv - 0.99seg]);
        track(rb[:ass.yv - 1seg, :ass.yv]);
        track(rb[:ass.yv - 0.1dl, :log.yo + 0.1dl]);
        track(:station, rb[:log.yo, :log.yo + 1seg]);
        track(rb[:log.yo + 0.99seg, :log.yo + 0.71km]);
        line_label(:left:n, rb[:log.yo + 0.7km] << 0.5mt, "RBB");
        track(rb[:log.yo + 0.69km, :log - 0.49sw]);
    }

    with link = "point.dk.Løgumkloster", railway = :station {
        track(rb[:log - 0.5sw, :log + 0.5sw]);
        marker(:right :de.inbf, rb[:log] >> 0.5mt);
        station(:bottom, rb[:log] << 0.5mt + (1dt, 1dt),
            span(:former, "Lügumkloster"),
            span(:bold, "Løgumkloster"),
            "RBB: 27,3"
        );
    }

    with link = "line.dk.RBB" {
        track(rb[:log + 0.49sw, :ell - 0.49sw]);
    }

    with link = "point.dk.Ellum", railway = :station {
        track(rb[:ell - 0.5sw, :ell + 0.5sw]);
        marker(:left :de.hst, rb[:ell] << 0.5mt);
        station(:bottom, rb[:ell] << 0.5mt << 1sh + (1.2dt, 0.9dt),
            "Ellum", "RBB: 30,4"
        );
    }

    with link = "line.dk.RBB" {
        track(rb[:ell + 0.49sw, :ell + 2.71km]);
        line_label(:right:s, rb[:ell + 2.7km] >> 0.5mt, "RBB");
        track(rb[:ell + 2.69km, :bre.xr]);
        track(:lor,
                rb[:bre.xr - 0.1dl, :bre.xr]
            ..  rb[:bre.yr, :bre.yr + 0.1dl] >> 1mo
        );
    }
}

